const CHANGELOG19=[{"version":"Alpha Version 1.26","date":"November 9, 2026","title":"HD worlds and living scenery","items":["Replaced all twenty battle landscapes with newly generated native HD day/night pairs. Refined panorama size, perspective, distant focus and sampling while keeping characters and interface text sharp.","Matched physical battle scenery to each landscape: ruined arcades, orchard walls and sheds, cypress avenues, cave crystals, alpine ledges, snowy cornices, coastal chalk, windmills, standing stones and seasonal planting.","Added regional battle mist, light shafts, waterfall spray, sea haze, smoke, cold drift, crystal light and moving foliage. Cinematic and action cameras retain bounded landscape coverage across desktop and phone views.","Replaced environment surface art throughout the overworld, POIs, interiors and battles with native HD materials and matched normal, roughness and surface data. Wood, soil and stone remain matte; glass, polished metals and water retain their appropriate reflections.","Introduced varied meadow, forest-floor, trail and paving textures, with irregular patches and continuous world-space blending to reduce repeated ground patterns.","Rebuilt grass, ferns, flowers, leaves and connected woody shoots as modeled 3D vegetation. Added fuller species-specific crowns, needle clusters, orchard blossoms, autumn colors, snow cover and wind motion shared with their shadows.","Reworked rocks into varied weathered forms with rounded edges, strata, cracks, mineral detail and habitat-aware moss. Added location-specific gardens, undergrowth, scree and coastal planting.","Made battle planting follow the actual paving, slope, rock, water and building-footing exclusions. Removed the retained old grass pass from stone floors and kept the fighting field readable.","Replaced plaster window panels with reflective glazing and recessed room imagery. Corrected authored house and hall orientations toward their streets, completed residential walls and gables, and fitted masonry bases and entrance treads to the terrain.","Rebuilt town wells with hollow stone bowls, recessed rippling water and connected posts, winding beams, ropes and buckets.","Refined landscape lighting, sky fill, air depth and material response. Updated river normals, shallow-water detail, foam and caustics while preserving the exact shared water join between POIs and their background.","Cleared large foreground tree crowns from the party view without removing their shadows or reflections. Refreshed loading views, retained bounded phone texture budgets, and preserved the approved party, NPC, monster and interface artwork."]},{"version":"Alpha Version 1.25","date":"November 8, 2026","title":"Four-person parties and clearer battle staging","items":["Limited the active traveling and combat party to four companions.","Added reserve companion controls to Party. Swap companions while exploring without losing their levels, equipment, HP or MP; story play keeps Bren in the active party.","Migrated existing five-person saves to four active companions plus a reserve, preserving all five characters and their progress.","Reframed combat around the reference composition: larger fighters, two staggered party ranks on the right, enemies on the left and a full-viewport desktop camera. The hooked-beak bird now uses its larger battle scale without enlarging overworld wildlife.","Refined distant landscape framing, clearing soil and planted scenery. Foreground trees are placed clear of the fighters, keeping faces and weapons visible.","Moved phone NPC and monster cards beneath their targets in portrait and landscape. Crowded large enemies use a compact row below the group, with individual connectors and working target taps.","Kept status effects, counters and discovered weaknesses visible on phone enemy cards, using consistently sized native icons in a horizontally scrollable row.","Updated the dev battle tester to use four as its full-party limit and retain a chosen four-person lineup when starting another battle."]},{"version":"Alpha Version 1.24","date":"November 8, 2026","title":"Steadier travel and clearer combat","items":["Fixed fast travel from the Escape-menu map leaving the title-style pause open. The chosen destination is retained through the transition, gameplay resumes at the real arrival, and invalid destinations are rejected.","Restored the full viewport projection after combat, correcting squeezed or skewed views in the overworld, POIs and interiors.","Moved the party farther right and kept enemies on the left in staggered formations, with adaptive silhouette fitting across desktop, ultrawide and phone layouts.","Enlarged the three Commanders by about two-thirds while preserving ordinary creature sizes and fitting the larger silhouettes clear of combat controls.","Gave all six human-opponent families reviewed, armed native ready and guard poses. Soren retains his authored combat animations, and exploration poses remain separate.","Synchronized party and enemy meshes, facing and combat frames before the first reveal frame so story battles no longer briefly show the old exploration row or neutral poses.","Made ordinary enemy attacks vary among eligible party members. Hunters retain a modest wounded-target preference; defeated and untargetable members are excluded, and temporarily untargetable parties no longer stall the enemy turn.","Scoped notice boards to their own optional requests, stopped nearby NPCs relisting those same board jobs, and labeled board and NPC request sources separately in the Journal while preserving progress, tracking and rewards.","Rerecorded recovery reactions for all five party members with their existing approved voices and stronger battle delivery.","Aligned injury and recovery checks with the 25% HP pose boundary. Recovery is announced once when healing moves a living character above the threshold; further healing above it does not repeat the line."]},{"version":"Alpha Version 1.23","date":"November 8, 2026","title":"Richer battles and sharper phone visuals","items":["Placed enemies on the left and the party on the right in staggered rows, with spacing fitted to the actual character silhouettes across desktop, ultrawide and phone layouts.","Refined battle distance and perspective, lowered the portrait-phone camera, and preserved the proportions of the distant scenery.","Restored the eight cinematic reveals and the earlier attack-camera pans and pushes, with gentler phone motion, stable handoffs and respect for reduced-motion settings.","Bound cinematic and action cameras to the landscape coverage so reveals keep the picture edges and backstage space out of view. Corrected transparent borders and cloud blending around the paintings.","Shaped every battle stage around raised, uneven banks and a clear fighting hollow, with layered stone ledges and foreground framing that retain real depth during camera moves.","Added rooted groves, ferns, flowers, fallen wood, rubble, small stones, farm details and regional landmarks between the fighters and the original day/night paintings.","Gave all twenty stages regional lighting and ground palettes, with warmer orchards and sunsets, cooler snow and caves, and lighting matched to the selected daytime or nighttime landscape.","Added restrained background waterfall flow, moving water highlights, foliage and cloud shading, crystal glow, drifting leaves and airborne effects where they suit the scene.","Matched orchard trees to the green apple trees in their painting, added attached fruit, and restored snow cover to the snowfield branches.","Seated arch legs and building foundations on the terrain, rebuilt fence rails and royal walls to follow their banks, and connected stone bridge decks to their approaches.","Rendered common phone screens at their native 2x or 3x density within a pixel budget, preserved crisp sprite filtering, and reduced excessive battle blur on phones.","Enlarged small phone HUD, combat and menu labels and reduced text glow, while preserving the approved character artwork and its native pixel resolution.","Kept fighters grounded through screen rotation and deferred formation changes during active attacks. Characters return to the correct new positions when their action ends.","Kept scenery and effects batched, cached stable camera checks, retained low-quality rendering options, and verified that animations reuse geometry and battle resources are released on exit."]},{"version":"Alpha Version 1.22","date":"November 7, 2026","title":"Renewed characters and layered battles","items":["Rebuilt Bren with consistent proportions, clean native pixel edges, eight-direction full-run movement at both travel speeds, and breathing exploration idles.","Replaced Bren’s normal and Ascended combat animations with breathing ready poses, complete sword swings, Driving Slash, guard, recoil, Rally, injury and victory. Larger source frames preserve the full blade and hand placement.","Rebuilt Soren’s eight-direction movement and combat poses. His battle entrance lifts him into the approved slight hover, with a breathing ready loop, staff attacks, Arcane Pulse, Ward, guard, recoil, injury and victory.","Added layered sword ribbons, impacts, runes and magic flashes whose colored light reaches nearby terrain, props and actors. Reusable effect pools clear correctly when encounters end.","Replaced seventeen world NPC families with reviewed PixelLab designs, eight-direction movement and breathing idles. The other thirteen keep their current playable animation sets while their new designs remain available as staged developer previews.","Upgraded exterior, overworld and interior material families with distinct wood, bark, stone, plaster, cloth, metal, pottery, leather and paper finishes. Native normal detail and surface-specific roughness keep matte surfaces matte.","Reworked connected tree boughs, species-specific foliage and bark, fractured rock shapes, ground cover and interior material variation using the new native PixelLab art.","Added an NPC, party and creature browser to the existing developer console, with animation selection, direction and frame controls, playback, contrasting preview backgrounds and current/staged NPC comparisons.","Added PNG/JPG downloads for displayed sprites and ZIP exports for every frame of a selected animation or a character’s complete animation set.","Added combat enemy, enemy-count and encounter pickers to the developer console. The existing protected toolbar remains usable on portrait and landscape phones.","Rebuilt all twenty battle environments around detailed physical foreground terrain, rooted 3D middle-distance scenery and the original paired day/night PixelLab paintings set farther behind the battlefield.","Removed smeared picture colors from the terrain beneath fighters and reduced oversized foreground planting. Native trees, rocks, architecture, crystals and rotating windmill sails bridge the physical field and distant scenery.","Added calibrated background depth, parallax, moving foliage and water, airborne effects, soft distant focus and restrained bloom. Cinematic reveals hand off to a stable gameplay view with sharp characters.","Staged party members and enemies in staggered groups instead of a straight line. Native sprite silhouettes determine spacing, and action animations return actors to stable formation positions.","Kept battle actors grounded when the viewport changes orientation, reserved space for combat controls, and moved large enemies clear of the phone landscape command dock.","Restored the earlier river finish and joined background water to the POI water with matching material, flow, edge positions, depths and changing levels. Corrected stale and self-reflected background water at the join.","Refined fountain and well water with the shared native ripple, shallow-depth and reflection treatment.","Made ordinary human opponents and commanders use the same pixel defeat effect as other enemies, while retaining Soren’s explicit story withdrawal. Enlarged commander presentation without changing ordinary enemy sizes.","Added injury and recovery voice reactions for all five party members, with threshold tracking, serialized playback and safeguards against repeated or defeated-character reactions.","Made reward notices remain visible for four seconds, added a brief slide transition, and preserved manual dismissal and queued rewards without duplicate grants.","Made Escape reliably open the main menu around destination prompts, removed the duplicate main-menu action in Settings, and cleared residual battle interface after leaving an encounter.","Reused scene geometry, native material batches, effect pools and the battle post-processing target. Background paintings decode on demand during the encounter transition, and owned combat resources are released on exit."]},{"version":"Alpha Version 1.21","date":"November 6, 2026","title":"Connected roads and steadier journeys","items":["Rebuilt all fifteen overworld destinations as natural miniature settlements and landmarks, with individual grounded buildings, open ruins, cave outcrops, shrine rings and irregular groves.","Replanned destination approaches around the regional roads. Twenty geographically appropriate entrances now match their local exits; removed unused gates instead of placing an exit in every direction.","Connected roads directly to the visible destination gateways and settlement centers. Dry curved approaches reuse existing river crossings, and the invisible woodland boundaries follow the revised paths.","Rebuilt all seven overworld bridges with open stone arches, masonry details, parapets and endpoint lamps. Raised decks and graded approaches cross continuous water; relocated the river-fork crossing away from the mid-span land spur.","Smoothed world-road surfaces and shoulders while keeping the terrain, real 3D world map, miniatures and bridge approaches aligned.","Fixed black flashes caused by adaptive resolution changes. Canvas resizing now completes its replacement frame before presentation and skips unchanged dimensions.","Preserved named arrival and return gates after the final scene is ready, including cached scenes. Entry and exit use connected, dry and walkable points on the appropriate side.","Separated overworld companions with a longer collision-aware trail, including five-member parties, while preserving local-scene spacing and movement speed.","Escape now opens the opening game menu during play, with Resume game and access to New Game, Continue, Load Game, Settings and Credits. Resuming preserves the current scene and party position.","Stopped enemy hover from changing the selected combat target. Click and Tab / Shift+Tab choose living targets while the ring and arrow stay on the selected enemy.","Stabilized the combat tutorial dock and its Begin Lesson / Continue controls so pointer movement no longer makes the prompt jitter.","Enlarged enemy status icons and turn counters and expanded their display space, including phone combat layouts, while keeping the battlefield and timing controls clear.","Matched centered world narration to the approved ivory serif treatment with a stronger diffuse dark glow and a title-case The World header. Kept the scene visible without a panel and corrected phone centering and wrapping.","Fixed shopkeepers turning backward inside forward-facing idle and walking animations by selecting verified native PixelLab poses. Counter staff hold the customer-facing direction while idle and face customers during service interactions.","Audited eight service-character sprite sets across all eight directions. Preserved their original pixel art, proportions and ground anchors; verified inn service, supplies and equipment purchases."]},{"version":"Alpha Version 1.20","date":"November 5, 2026","title":"Clearer combat and a smoother journey","items":["Rebuilt mobile combat around a visible battlefield, compact party cards and a bottom command dock. Portrait and landscape layouts keep the fighters clear of controls and readouts.","Aligned the battle camera, painted backgrounds and 3D ground. Landscape scenes retain the lower clearing so characters stay planted in both day and night.","Made phone rotation resize the battle render immediately. Whole-device-pixel rendering, up to 2x on compatible phones, keeps the original sprites sharper; Performance mode retains its lighter render budget.","Moved optional combat guidance into Help on phones while preserving held tutorial lessons, Continue controls, MP costs and the full icon legend.","Kept tutorial prompts and enemy HP panels clear of the attack timing meter on desktop and phones. Three-hit attack chains and target selection retain their normal controls.","Defeating the selected enemy now moves selection to a living enemy automatically. Target arrows and rings disappear when no valid enemy remains.","Rebuilt treasure chests with a hollow lined interior, curved wooden lid, brass fittings and a smooth hinge animation with a brief glow and drifting motes.","Opened chests stay open after returning. Stable chest identities across town districts preserve old saves and prevent repeated loot grants.","Restored reliable inn and shop interaction anchors on the customer side of counters. Hosts and vendors face customers from their actual positions before service menus open.","Added confirmation and cancel controls for abandoning accepted optional requests in the Journal. Abandoned requests can be accepted again; story objectives and claimed rewards remain protected.","Moved blocked local request objectives onto connected, walkable paths. A Clear Way Home can be completed inside the playable boundary, with rewards granted once.","Restored the map marker and interaction for A Choice of Restraint in Fern Hollow when Tavin is the controlled character.","Made POI re-entry follow the current approach side instead of a remembered previous exit. Interaction anchors remain aligned with their visible diorama gateways.","Restored Escape menu access beside overworld destination prompts. Resume game / Esc and a prominent Main menu button now appear at the top of Settings.","Revealed the complete minimap layout immediately inside entered towns, interiors and other local locations. Overworld exploration and undiscovered service details retain their discovery rules.","Straightened Fern Hollow camera alignment and kept its north/south road centred on the leader.","Corrected sprite depth at walls and counters, removing false silhouettes while preserving the outline when scenery truly hides a character.","Rebalanced overworld party size for readability while preserving proportions, local-scene scale, movement speed and collision. Mirrored sprites keep their upright vertical scale.","Refined phone exploration, maps, menus, weather, touch controls and the developer console across portrait and landscape screens, including safe areas and scrolling.","Replaced four outdated loading images with native 1920x1080 game photographs showing walking, conversation, shopping and reading, with characters clear of furniture.","Reused the completed continent during travel and retained one town exterior while visiting its buildings. Cached GPU resources avoid repeated rebuilding and shader preparation on return.","Bounded nearby weather preparation and packed visible rain into one batch. Detached hidden rain cells prevent duplicate draws after building visits, and fine grass avoids a redundant animated shadow pass.","Kept atmospheric haze and sun shafts above horizontal ground so paving and terrain shadows stay clear while the surrounding air retains its atmosphere."]},{"version":"Alpha Version 1.19","date":"November 5, 2026","title":"A richer world and better interiors","items":["Refreshed character proportions across 38 humanoid variants, including party members, residents and the Soren opponent. Native movement and combat-facing sprites stay grounded as the camera moves.","Rebuilt all seven active interiors as furnished wall-top cutaways with clear routes, real window openings and consistent day/night layouts. Removed misplaced rear doors and overlapping wall fittings.","Repaired furniture and decoration placement throughout the inns, supplies shop, smithy, archives, council chamber and aid office. Added missing supports, corrected shelf and rope placement, cleared window obstructions and replaced the archive record box with a reading lectern.","The smithy now has one clearly visible blacksmith, four complete mounted swords and unobstructed armor displays. Rebuilt all seven hammers and the anvil with connected parts and proper worktop or stump contact.","Moved service NPCs into clear view while preserving merchant purchases, lodging, story conversations and exits. Archive records now keep their full reading dialogue instead of advancing after one speech bubble.","Unified exterior and interior material response with native PixelLab surface detail, normals and material-specific roughness. Cleaner plaster replaces the speckled wall finish; reflections belong to metal, glass and water.","Replaced the flat save marker with a brighter animated seal, two fluid energy ribbons, independently drifting motes and a moving local light. Inn seals fit a reserved floor bay; outdoor placement and save functionality are preserved.","Rebuilt all fifteen overworld destinations as distinct miniature courts with dry approach roads and clear entrances. Terrain-fitted gateway posts and solid stairs connect the road to raised foundations, and physical footing matches the steps.","Destination entry still requires E. Leaving a location returns the party to its matching gateway. Highmere has a clear dry approach and one river crossing.","Reworked woodland silhouettes with connected branches and alpha-cut foliage instead of opaque canopy cores. Irregular forest clusters, open ground and clear approach lanes retain the continent boundaries.","The M world map now renders the actual native overworld meshes, miniature buildings, water and forest positions instead of a separate low-resolution copy. Opening it indoors retains outdoor illumination; minimap clicks still open the local map.","Reduced startup work with six parallel image decoders and removed obsolete battle and destination warm-up builds. Destination shaders compile during covered transitions, and entrance stair queries use a compact spatial index."]},{"version":"Alpha Version 1.18","date":"November 4, 2026","title":"Living battles, clearer combat and a smoother journey","items":["Added eight authored battle opening camera paths with a smooth handoff into combat, protected input/timers, reduced-motion options and safe camera fallbacks.","Rebuilt battle scenery around the approved backgrounds with separate ground, banks and distant depth surfaces, matching solid rocks and rooted edge trees. Camera moves reveal depth while the cast stays grounded.","Added restrained water and waterfall motion, wind-blown foliage and fine grass. Removed oversized mismatched scenery, bright ground blobs and distracting foreground clutter while preserving all twenty day/night stage pairs.","Introduced twelve distinct rock forms, connected tree growth and a shared light-responsive water treatment across the overworld and local scenes.","Brought the battle, day/night and scene testers into a password-gated developer console hidden in the changelog. Its toolbar stays at the top and adapts to portrait and landscape phones.","Improved phone layouts, safe areas, scrolling and orientation changes across menus, tester controls, dialogue and combat.","Allowed the party to pass NPCs and individual overworld trees while preserving building, water, local-tree and continent boundary collision.","Kept scenery opaque and added an animated player silhouette when the controlled character is behind buildings or trees.","Removed the loading screen outer frame and the custom F fullscreen shortcut. F11 remains available through the browser.","Removed dialogue-advance click sounds, unified E interaction prompts and gave world narration a centered, frameless presentation.","Added matching quest icons above relevant NPCs and on the minimap, with acceptance/completion updates independent of compass tracking.","Reduced repeated scene preparation by reusing vegetation, route and boundary data, stable light slots and compiled material families.","Preserved the approach side when entering or leaving POIs through named entrances; corrected arrival and return points across all fifteen destinations.","Unified standard enemy defeat dissolves and sprite-colored particles. Defeated enemies immediately stop acting and cannot be targeted; rewards remain once-only.","Integrated ten approved ability-type icons and eighteen buff, debuff and status icons, with turn badges, descriptions and an accessible in-game legend.","Enemy weaknesses now begin hidden and are learned only through successful matching hits. Discoveries are tracked separately for each enemy and type during the current battle.","First discoveries trigger a brief confirmation and the attacking character’s own queued voice reaction. Matching discovered weaknesses show WEAK during ability targeting without leaking unknown affinities.","Polished damage and healing numbers with clear outlines, distinct healing treatment, controlled impact motion and camera-following actor anchors. Rapid hits receive separated positions.","Aligned combat with the approved HUD: compact turn portraits above, commands and Skills in the upper right, smaller tightly spaced party cards below, and contextual help clear of the timing meter.","Formal story objectives and optional quests now grant EXP plus curated randomized loot alongside guaranteed rewards. Saved completion receipts prevent duplicate grants.","Added seven consumable magical combat gems: Fire, Ice, Water, Lightning, Wind, Earth and Poison. Rewards display EXP, items and quantities clearly."]},{"version":"Alpha Version 1.17","date":"November 3, 2026","title":"A clearer world, richer maps and distinct battles","items":["Rebuilt the traversal landscape with subtle rolling ground, valleys and mountain ranges. POI foundations, roads, coastlines and the 3D atlas now share the terrain.","Made overworld bridges cross real water with submerged riverbeds, dry approaches and walkable decks.","Replanned all fifteen POIs with larger connected streets, service courts and clearer boundaries. Moved wilderness destinations away from town miniatures and improved building orientation.","Matched invisible boundaries to the expanded pathways. Denser, irregular forests, mixed tree ages and mountain edges blend the impassable areas into the environment.","Made POI departures, overworld destination entry and building doors deliberate E interactions, with contextual prompts and scene fades instead of automatic transfers.","Grounded buildings, pedestals and crystals across their whole footprint, corrected buried structures and reduced flickering landmark surfaces.","Made visible residents available for conversation even outside their current story action, without advancing quests or granting rewards through idle dialogue.","Smoothed overworld party movement and kept the camera centered on the traveling party. Preserved collision-aware companions and scene-return positions.","Reskinned the world map and shared menus with native PixelLab navy-and-gold artwork, illustrated headers, ornamental frames, buttons and backgrounds.","Refined the settlement picker and navigation shortcuts. Town silhouettes remain visible before discovery while local interiors, services and unexplored details stay hidden until learned.","Rebuilt the north-up minimap with a matching gold compass, consistent live icons, a complete icon legend, zoom and a time-and-weather strip. Minimap clicks open the local map; M opens the world map.","Made quest guidance depend on explicitly tracking a quest. Limited recorded voice requests to combat moves and prevented text or artwork selection during play.","Added twenty regional PixelLab battle environments, including ten distinct grasslands, each with matching day and night art: forty native 688 by 384 backgrounds.","Moved random encounters into separate staged scenes with a flat combat floor, aligned actor feet and contact shadows. Battle return restores the exploration scene and party position.","Authored continuous predawn, dawn, morning, noon, afternoon, golden-hour, dusk and moonlight palettes for POIs and the overworld, with readable night paths, party silhouettes and nearby landmarks.","Added depth-aware atmosphere, foliage light and sun rays filtered by actual cloud cover and scene shadows. Softened cloud shadows and stabilized shadow projections during movement.","Fixed repeated cloud and sunlight shader decoration that caused growing shader counts and stutter. Reused shadow allocations and verified stable shader counts during sustained play.","Removed gameplay lens blur and prevented aggressive render-resolution reductions. Retained live lighting, rays, weather, shadows, battle controls and responsive phone layouts."]},{"version":"Alpha Version 1.16","date":"November 2, 2026","title":"Purposeful paths and a grounded party","items":["Replanned all fifteen POIs around connected main paths, service approaches, story courts and clear road-aligned exits. Natural stone, shrubs and trees define the playable routes.","Kept the approved atlas placement and story targets while removing empty outer road tails and random outskirts housing. Cleared obstructing route trees and painted the existing terrain across detail levels.","Preserved exact approach chains in navigation so distant exits and story interactions remain connected. Legacy arrivals settle safely inside the new routes.","Required movement into a doorway for automatic entry; street routes to other destinations no longer enter buildings accidentally. Actors can move out of a pre-existing crowd overlap while still respecting personal space.","Made companions keep pace with Shift sprinting while following their own collision-safe trail and running animation.","Interpolated wind and weather motion at presentation time and refreshed directional shadows for moving foliage and actors on every presented frame.","Strengthened ground-conforming underfoot shadows on streets, bridges, stairs and indoor floors.","Preserved ambient wildlife habitats outside the public paths and kept new boundary props clear of their roaming routes."]},{"version":"Alpha Version 1.15","date":"November 2, 2026","title":"Smoother motion, water and light","items":["Synchronized camera and character interpolation across display refresh rates to remove landscape judder while running.","Bounded simulation catch-up after long stalls, reused exact terrain queries within each step, and removed a duplicate flat foot-shadow layer.","Replaced layered river geometry rewrites with one cached row update and completed the downstream refill through the end of the channel.","Prevented water surfaces and mist reflecting back into neighboring water targets; restored transforms after every reflection pass.","Updated moving directional shadows every presented frame and retained the matching projection when reusing a stationary shadow map.","Anchored atmospheric scattering to fixed distance intervals with softened shadow sampling. Added denser world-space dust that responds to canopy and cloud shadows, with stable seeds across cell boundaries."]},{"version":"Alpha Version 1.14","date":"November 1, 2026","title":"Steadier surfaces in motion","items":["Stopped terrain, trees, ground foliage and their shadows repeatedly changing detail when movement hovered around a distance threshold. Wider entry/exit bands preserve adaptive rendering without rapid visual switches.","Replaced discontinuous atmospheric ray-sampling noise with continuous world-space variation, reducing movement-triggered brightness flashes without increasing scattering steps."]},{"version":"Alpha Version 1.13","date":"November 1, 2026","title":"A world shaped by its atlas","items":["Rebuilt atlas relief, coastal shelves and northern mountains with naturally blended climate transitions. Restored the green region’s Valenne and Brook rivers; replaced the desert cuts with winding tributaries, an oasis and one connected coastal outlet.","Moved the southern volcanic island farther offshore and south; its coastal harbor keeps its position on the moved island.","Replaced sparse map canopies and patterned ocean water with fuller native forests, depth-based coastal color and a whole-world view.","Rebuilt Fern woodland houses as covered timber pavilions, strengthened Highmere civic silhouettes, and dressed the relief and shelter courts.","Replaced the outdoor meadow in the Fern remnant with a textured stone vault and ancient spindle mechanism. Removed inherited houses from wilderness patrols, ruins and Elder Light clearings.","Added monument pedestals, weathered ruin arches, natural outcrops and roadside flower drifts while reserving road shoulders and story interaction space.","Integrated a new 512-pixel PixelLab cliff texture and matching normal map, with triplanar cliff mapping to avoid stretched rock stripes.","Joined overworld crossings with continuous banks and physical bridge approaches. Verified all 15 destinations against atlas positions and usable trail thresholds.","Gave each POI a natural JRPG perimeter with clear openings, glowing floor arrows at actual doors and trail mouths, and walking or E transitions. Overworld entry spots sit beside the road instead of on shrines.","Fixed Fern’s riverbank exit and E targeting at doors beside villagers. Added snow on foliage, alternating snow tracks and pooled contact shadows directly beneath visible characters and creatures.","Integrated a new 512-pixel PixelLab river current texture and subtle normal map. Water junctions share one triangulated surface; continuous shaped banks replace square traced channels."]},{"version":"Alpha Version 1.12","date":"November 1, 2026","title":"A steadier journey and a more distinct world","items":["Fixed simulation timing so movement, combat and the day cycle keep their pace when presentation frame rates change. Fixed scene and water-shader cleanup found during long travel/combat sessions, and reduced redundant terrain and transform work on slower devices.","Added versioned journey records with stable quest identities, validation, recovery copies and portable file import/export for the three record slots.","Rebuilt campaign work actions with route recovery and visible helpers. The regional restoration visits all four repaired Elder Lights in saved order and can resume after loading.","Added encounter-specific rewards, speed-based turns, readable enemy intentions, weaknesses, stagger and consistent level growth. Protected the coached opening battle from premature defeats and repeated demonstration clicks.","Built distinct pitched woodland homes and pale-stone civic architecture from the current Drive concepts. Updated the atlas to 25 named places and modeled its three sourced coastal harbor landmarks.","Added seven approved-concept creature families, complete directional motion, larger native artwork for giant creatures, and physical species scales shared by exploration and combat.","Added detailed native stone and woodland materials with lighting normal maps, regional ElevenLabs ambience and creature foley. Local requests now include named gathering, delivery, repair and recording work.","Improved exploration camera framing, kept selected-enemy outlines thin at large creature sizes, and aligned attack effects with each target’s physical height."]},{"version":"Alpha Version 1.11","date":"October 31, 2026","title":"Faster starts, smaller memory and steadier play","items":["Added a functional staged loader for reading the bundled file, decoding artwork and short sounds, compiling lighting, preparing weather, uploading textures and warming geometry before play.","Baked the actual overworld height field and tree positions. The 3D atlas keeps the same geography without retaining the continent’s close-up grass and canopy buffers.","Fixed departed scenes being retained by shader-material callbacks. Compiled programs now use a bounded cache; replaced party canvases and materials are released.","Shared immutable foliage buffers, reused native character planes, enlarged meadow batches and culled static branches with reflection and shadow coverage preserved.","Combined world-anchored rain and snow into one draw, prepared location weather samples behind loading screens and bounded overworld weather prefetch.","Added startup graphics calibration, constrained-device shadow/reflection cadence and appropriate render-target budgets. CPU pressure no longer needlessly blurs the scene.","Removed duplicate minimap rendering, cached unchanged party cards and radar content, accelerated fog-of-war records and removed redundant simulation catch-up work.","Prepared recorded voice URLs and decoded short effects before gameplay. All existing PixelLab art, detailed textures, abilities, lighting, saves and story content remain available."]},{"version":"Alpha Version 1.10","date":"October 31, 2026","title":"Elemental power, natural creatures and living light","items":["Rebuilt the wolf and boar combat profiles with new PixelLab side-view art, breathing, lunging, recoil and recovery poses. All native frames retain consistent scale and transparent borders.","Added six high resolution PixelLab effect textures for fire slashes, impacts, arcane lightning, frost, healing and smoke, animated as depth-tested world geometry with real effect lights.","Added pooled soft contact shadows beneath visible party members, residents and creatures, alongside their dynamic directional shadows.","Integrated cloud- and shadow-aware volumetric scattering with world-anchored shafts, luminous dust, warm dawn and golden-hour light.","Batched hundreds of bridge support stones while retaining authored walking decks, collision and texture blends.","Reduced repeated particle-buffer uploads and temporary effect allocations; retained bounded pools and tiered terrain, foliage, shadow and rendering budgets."]},{"version":"Alpha Version 1.9","date":"October 30, 2026","title":"Warmer light, steadier frames, a journey in your hand","items":["Rebalanced the continuous solar cycle with amber dawn and golden hour, clear midday, readable blue moonlight, glowing windows and warm light reaching nearby surfaces across the scene.","Added depth-aware lens focus that keeps the party and playable middle ground sharp, with a consistent blur radius across display densities.","Extended meadow coverage to 185 metres in locations and 230 metres on the overworld, with lower-detail distant foliage and conservative spatial visibility.","Coalesced window and orientation changes, removed resolution-dependent shadow-map thrashing and kept shadow, reflection and scene buffers within stable budgets.","Added CPU/GPU-aware detail tiers and render scaling with slow recovery, refresh-divisor pacing and fixed light slots to avoid compiling a new lighting variant during attacks.","Character textures now upload only the current native frame on an individual canvas, preserving the authored pixels, frame borders, facing and separate character sizes.","Enlarged foliage batches, cached bounded live road queries and tightened scene resource cleanup for repeated travel and extended play.","Rebuilt compact portrait and landscape layouts with journey shortcuts, expandable objectives, compact party cards, a touch joystick, sprint toggle and interaction button. Touch cancellation clears held movement.","Added larger separated touch targets for enemy selection and kept the full battle in frame in portrait mode. Strengthened pooled attack lights and highlight bloom so abilities illuminate the actual environment."]},{"version":"Alpha Version 1.8","date":"October 30, 2026","title":"Clearer routes, steady characters and flowing water","items":["Removed the mismatched front-facing Soren idle poses while preserving the complete native coat animation.","Kept physical bridge decks visible through scene trimming and cutaways, and extended terrain beneath enlarged approaches.","Removed stray neighbouring road strips, continued roads past exit markers and rerouted the Network approach around its cliff.","Matched walking heights to the fine road surfaces and removed road-blocking rocks without a valid relocation.","Restricted the remnant rock overhang to its own location, reserved full road clearance and moved noticeboards to walkable shoulders with collision only while visible.","Slowed the sluice release and downstream recovery; water now clears the stone sill before the lower pools fill.","Removed the sweeping current ribbon and obsolete spray, with slower flowing surface and cascade textures.","Replaced overlapping old cloud planes with a bounded, rounded cloud volume linked to the moving sun, shadows and light shafts.","Cleaned up previous weather chunks during repeated setup and kept outdoor light, dust and cloud colours tied to the day/night cycle."]},{"version":"Alpha Version 1.7","date":"October 30, 2026","title":"A moving sky, a better-built world","items":["The sun now crosses the sky from east to west. Fourteen smoothly blended colour keys tint direct light, sky, clouds, ambient fill, haze, shafts and dust: violet predawn, peach sunrise, blue midday, amber golden hour, rose dusk and cool moonlight.","Moving volumetric clouds share one world-space field with surface shadows, sunlight shafts and airborne dust. Clouds interrupt the light, while persistent rays stay anchored in the landscape.","Rebuilt settlement facades with recessed doors, fitted awnings, complete roof ends, framed windows, properly seated chimneys and clear entry steps. Removed overlapping inn additions and duplicate facade layers.","Forest homes now have closed curved roof ends and fitted porches. Relief pavilions have colliders around real posts, rear panels and furniture, allowing passage under the open canopy.","Rearranged shop and smithy shelving, weapon displays and service counters. Back doors remain clear, and the aid office now has its own desk, waiting area and storage.","Window light changes at dusk. Outdoor pollen, night fireflies, cool ambient fill and cloud-filtered sunbeams respond to the continuous clock and weather. Loading stills show the rebuilt in-game village and rooms."]},{"version":"Alpha Version 1.6","date":"October 30, 2026","title":"Living gardens, clearer light","items":["Fixed trees failing to reveal the party: every foliage detail level now shares the same individual-tree cutaway mask, while real shadows and water reflections retain the complete tree.","Rebuilt the forest as branched 3D crowns of folded, transparent PixelLab leaf sprays. Oaks, birches, maples, willows, spruces and flowering trees vary in shape, height, colour and placement.","Added five flower forms, curved grass tufts, folded ferns and leafy shrubs, planted in stable roadside and garden clusters. Removed the black distant shrub geometry.","Integrated 17 native 512px PixelLab assets, including paving, mossy paving, slate, plaster and meadow textures with matching normal maps. Material scale makes individual stones and roof courses more readable.","Moved the sun to illuminate building fronts, balanced warm sunlight against cool fill, reduced pale haze and broad additive rays, and preserved fine detail through gentler focus and bloom.","Adjusted the exploration lens for a closer diorama view with a slight diagonal angle. Forest batching uses larger cells and shared detail levels; loading stills now show the current in-game artwork.","Optimized live water reflections with a cropped reflected view that draws only scenery sampled by visible water, preserving the full projective image and immediate updates. Inactive botanical detail levels are released during travel."]},{"version":"Alpha Version 1.5","date":"October 30, 2026","title":"A warmer welcome indoors","items":["Rebuilt all seven active interiors with a closer, front-facing camera pitched down 25 degrees, including responsive tracking on narrow screens.","Added four native PixelLab interior assets: chestnut wall panels, detailed hearth stone, a woven rug and framed riverland artwork. Stocked shelves, table settings, chairs, banners and plants bring the rooms to life.","Added an open, animated fireplace and warm pooled lighting that affects characters and furnishings. Counter heights keep hosts readable, with clear routes to services, exits and inn save seals.","Fixed the missing objective for A choice of restraint. Tavin now has a visible encounter seal and affected villagers at the gathering ground; the marker clears after victory.","Replaced the old loading still with four fresh 1080p captures of the actual village, inn, shop and archives. Loading artwork now follows the destination, with no interface baked into the images."]},{"version":"Alpha Version 1.4","date":"October 30, 2026","title":"Sharper surfaces, smoother travel","items":["Fixed scenery trimming detaching party sprites during fast travel. Destination arrival now restores the full party and checks the destination camera before showing the scene.","Removed uneven refresh-deadline frame skipping. Small screens use appropriately sized reflection and shadow buffers, with stable high-DPI resolution and idempotent resizing.","Replaced the Map icon with a clear PixelLab parchment map and kept an opaque navy-and-gold plate on hover and keyboard focus.","Added ten new native 512-pixel PixelLab world surfaces and nine matching normal maps, covering limestone, paving, plaster, slate, oak timber, meadow turf, soil, foliage and waterfall detail.","Restored physically based lighting for buildings and terrain, with material roughness, native normal detail, wet response and surface-attached crevice shading.","Added folded leaf fans to instanced tree crowns, planted flower clusters beside clear paths and doubled world-anchored floating dust particles.","Improved water depth colour, downstream ripples, broken reflections, textured cascade flow and subtle world-space spray.","Balanced warm directional light with cool sky fill and added restrained depth-selective diorama focus while keeping the playable middle ground sharp."]},{"version":"Alpha Version 1.3","date":"October 30, 2026","title":"Clearer battles and roads worth exploring","items":["Kept the entire sluice gate, frame and stone supports together through scene batching, reflections and visibility updates. Bren now works from the correct side of the wheel. House cutaways now include main roofs in every settlement, without reacting to projecting ornaments.","Extended every POI approach and departure road with larger outskirts, more housing plots, smooth grades and glowing outward-facing exits.","Linked persistent long sunshafts and moving sky clouds to the same world-space shadow field; lantern changes fade smoothly.","Rebuilt Equipment and Inventory with illustrated character panels, live comparisons, item inspection, recipient selection, sorting and filters. Added high-resolution PixelLab portraits and distinct item artwork.","Added purchasable accessory and off-hand fittings with real MP/defense bonuses and working equip/unequip actions.","Moved monster health bars beneath their sprites, enlarged the target arrow and added a glowing red silhouette outline that preserves enemy colours.","Kept all round participants in the turn order and marked completed, current and defeated turns instead of removing entries.","Batched grass and flower patches into fewer colour and shadow submissions while retaining individual wind, interaction and cutaway masks."]},{"version":"Alpha Version 1.2","date":"October 29, 2026","title":"A continuous world, a clearer journey","items":["Rebuilt the title around a live Brookstead river view with the supplied gold crystal wordmark, PixelLab navigation artwork, credits and a chronological release history.","Matched the loading screen to a sharp still from the same village camera, with actual loading progress and journey tips.","Rebuilt Journal, Inventory, Party, Equipment and Settings around the navy-and-gold references, with new PixelLab frames, scenery, compass and illustrated icons.","Added character recipient tabs, inventory filters, equipment comparisons, quest history, lore/help pages and grouped settings while preserving the live game data and controls.","Made distant scenery use the foreground terrain shader, multi-cluster trees, flowers and complete house meshes; removed overlapping terrain and continued the river past the village.","Rebuilt sluice supports and separated overlapping stone caps. Fitted complete railings along all four stair flights and landings.","Added varied ground-conforming rain puddles using river artwork, reflected sky, wet edges and ripples.","Anchored sunbeams in the world and linked their brightness to large moving cloud shadows.","Retained full-resolution rendering, spatial vegetation batches, responsive laptop/phone layouts, and three-slot save, load, overwrite and delete controls.","Fixed retained terrain LOD meshes and released instance buffers across repeated travel, preventing geometry counts from growing during extended play."]},{"version":"Alpha Version 1.1","date":"October 29, 2026","title":"Light, weather and a clearer view","items":["Replaced the extra projected character silhouettes with animated alpha-tested shadows from the actual scene light.","Aligned outdoor exploration straight ahead, with a gentle downward view closer to the battle camera.","Added dimensional overhead cloud volumes and soft depth-tested shafts sharing the moving cloud-shadow field.","Made sluice visibility and moving gate transforms independent of static scene culling.","Rebuilt rain puddles as irregular ground-conforming surfaces with ripples, sky reflections and gradual drying.","Separated wet stone, timber, foliage and character shading, removing painted-looking highlights on trees.","Removed overlapping circular ground pads at community pavilions and the relief-station title view.","Scaled the HUD for laptops, tablets and short displays, with a compact phone layout and scrollable party cards.","Improved narrow-screen menu navigation, dialogue and title layouts.","Replaced the expandable feature catalogue with this dated, readable release history."]},{"version":"Alpha Version 1.0","date":"October 29, 2026","title":"Initial alpha release","items":["Introduced the regional Elder Light story, five companions, six story battles and four Light restorations.","Built the playable overworld, fifteen points of interest and seven interiors, with a 3D discovery atlas and fast travel.","Added the gate and pump waterworks, village routines, interactions and fifteen optional local requests.","Implemented eight-direction running, Shift sprinting, trailing companions and object clearance.","Added side-on turn-based combat, timed attack chains, skills, items, guarding, Ascension and results/growth screens.","Integrated the approved PixelLab cast, 4,878 native poses, portraits, surface textures and loading illustrations.","Added 259 ElevenLabs voice performances and 93 music, ambience and effects recordings.","Implemented inventory, equipment, shops, inn recovery and three journey slots at inns and location entrances.","Added text-only guided field lessons and the scripted opening combat tutorial.","Introduced changing time of day, weather, moving cloud shade, flowing rivers, reflections and reactive foliage.","Rebuilt the title screen with cycling live locations, save previews, deletion and overwrite confirmations.","Expanded POI approaches and exits, introduced the gold PixelLab HUD, corrected roofs and repeated building cutaways, and optimized resident navigation, reflections and sustained native rendering."]}];
const title19={tab:'news',ready:false,stopped:false,busy:false,task:null,age:0,index:-1,bag:[],scene:null,focus:null,confirmation:null};
const TITLE_SCENES19=[['brookstead',[-121,66],'Brookstead · The fountain court'],['brookstead',[-154,77],'Brookstead · The waterworks'],['fern',[112,60],'Fern Hollow · Beneath the trees'],['highmere',[-78,-100],'Highmere · The royal quarter'],['alder',[137,-87],'Alderbridge · A place of shelter'],['relief',[43,-146],'Royal relief station · The relay court'],['harbor',[321,68],'Valenne · The coastal harbor'],['fernClearing',POIS.fernClearing.spawn,'Fern Hollow · An Elder Light']];
function saveSummary19(slot){const s=readSave(slot),raw=['v5','v4','v3'].some(v=>{try{return!!localStorage.getItem('elyndor-save-'+v+'-'+slot);}catch{return false;}});if(!s)return{slot,raw,valid:false};const beat=BEATS[s.beat],scene=INTERIORS[s.scene]?.name??SCENES[s.scene]?.name??POIS[poiFor(s.scene)]?.name??s.scene;return{slot,raw,valid:true,scene,chapter:CHAPTERS[beat[1]],objective:beat[2],savedAt:s.savedAt,elapsed:s.elapsed??0,members:(s.members??[]).filter(id=>CAST[id]),characters:s.characters??{}};}
function saveTime19(n){const h=Math.floor(n/3600),m=Math.floor(n/60)%60;return h+'h '+String(m).padStart(2,'0')+'m';}
function savedDate19(n){return Number.isFinite(n)?new Date(n).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Date unavailable';}
function saveCards19(canWrite=false){return['1','2','3'].map(slot=>{const q=saveSummary19(slot);return`<article class="journey-slot19" data-slot19="${slot}"><div class="slot-number19">0${slot}</div><div class="slot-copy19"><small>${q.valid?esc(q.chapter):q.raw?'UNREADABLE RECORD':'AN UNWRITTEN JOURNEY'}</small><h3>${q.valid?esc(q.scene):q.raw?'This record could not be read':'Empty slot'}</h3>${q.valid?`<p>${esc(q.objective)}</p><div class="slot-party19">${q.members.map(id=>`<span><img src="${assets.portraitFaces?.[id]??assets.portraits[id]}" alt="${CAST[id].name}"><b>${CAST[id].name}<small>Lv ${q.characters[id]?.level??1}</small></b></span>`).join('')}</div><footer><time>${esc(savedDate19(q.savedAt))}</time><span>${saveTime19(q.elapsed)}</span></footer>`:`<p>${q.raw?'You can replace or delete this record.':'Record your progress at a location entrance or an inn.'}</p>`}</div><div class="slot-actions19">${canWrite?`<button data-save="${slot}">${q.raw?'Overwrite':'Save journey'}</button>`:''}<button data-load="${slot}" ${q.valid?'':'disabled'}>Load journey <span>↗</span></button><button class="slot-delete19" data-delete19="${slot}" ${q.raw?'':'disabled'}>Delete</button></div></article>`;}).join('');}
function renderTitlePanel19(){const p=$('#title-right19');if(!p)return;const saves=title19.tab==='saves';p.classList.toggle('show-saves19',saves);p.innerHTML=saves?`<header><p class="eyebrow">YOUR JOURNEYS</p><h2>Pick up the thread</h2><p>Three slots · Stored in this browser</p><button data-title19="news">← Back to what’s new</button></header><div class="title-records19">${saveCards19(false)}</div>`:`<header><p class="eyebrow">THE JOURNEY CONTINUES</p><h2>${esc(CHANGELOG19[0].version)}</h2><p>Release notes · Latest changes first</p></header><div class="title-news19">${CHANGELOG19.map((q,i)=>`<article><div class="news-version19"><span>${i===0?'LATEST UPDATE':'PREVIOUSLY'} · ${q.version}</span>${q.date?`<time>${q.date}</time>`:''}</div><h3>${q.title}</h3><ul>${q.items.map(t=>'<li>'+t+'</li>').join('')}</ul>${(q.sections??[]).map(section=>'<details class="alpha-section21"><summary>'+section.title+'</summary><ul>'+section.items.map(t=>'<li>'+t+'</li>').join('')+'</ul></section>').join('')}</article>`).join('')}</div><footer>Progress stays on this device. Record at location entrances and inns.</footer>`;$('#title-load19')?.classList.toggle('active',saves);$('#continue-btn').disabled=!hasSave()||title19.busy;}
function setTitleBusy19(value){title19.busy=value;for(const b of $$('#title .title-buttons button'))b.disabled=value||b.id==='continue-btn'&&!hasSave();for(const b of $$('#title-right19 [data-load],#title-right19 [data-delete19]')){const q=saveSummary19(b.dataset.load??b.dataset.delete19);b.disabled=value||(b.dataset.load?!q.valid:!q.raw);}const next=$('.title-next19');if(next)next.disabled=value;}
function hideTitleParty19(){if(state.mode!=='title')return;for(const a of actors)if(a.party||CAST[a.characterId??a.id]||CAST[a.visualId]){a.mesh.visible=false;a.shadow.visible=false;}for(const id of['mentor-world-arrow17','combat-target-arrow']){const n=$('#'+id);if(n)n.hidden=true;}$('#journey-guide')?.classList.add('hidden');for(const o of world?.userData.partyReflections??[])o.visible=false;}
function nextTitleEntry19(){if(!title19.bag.length){title19.bag=TITLE_SCENES19.map((_,i)=>i);for(let i=title19.bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[title19.bag[i],title19.bag[j]]=[title19.bag[j],title19.bag[i]];}if(title19.bag.at(-1)===title19.index)[title19.bag[0],title19.bag[title19.bag.length-1]]=[title19.bag.at(-1),title19.bag[0]];}title19.index=title19.bag.pop();return TITLE_SCENES19[title19.index];}
async function switchTitleScene19(){if(title19.busy||title19.stopped||state.mode!=='title'||menu||title19.confirmation)return;setTitleBusy19(true);title19.age=0;$('#title-curtain19').classList.add('changing');const entry=nextTitleEntry19();title19.task=(async()=>{try{await new Promise(r=>setTimeout(r,240));if(title19.stopped||state.mode!=='title')return;const key=entry[0],p=POIS[key];buildWorld(p.id,entry[1]);title19.focus=[...entry[1]];title19.scene=key;hideTitleParty19();updateCamera(1,true);await prepareGameplayGraphics();if(state.mode==='title'){$('#title-location').textContent=entry[2];hideTitleParty19();updateCamera(1,true);render();}}finally{setTitleBusy19(false);$('#title-curtain19').classList.remove('changing');title19.task=null;}})();await title19.task;}
function installTitle19(){if(title19.ready)return;title19.ready=true;const old=$('#title'),nav=old.querySelector('.title-buttons');old.querySelector('.title-copy').insertAdjacentHTML('beforeend','<p class="title-control19">Choose with the mouse or ↑ / ↓ · Enter to confirm</p>');const load=document.createElement('button');load.id='title-load19';load.dataset.title19='saves';load.innerHTML='Load journey <span>↗</span>';nav.insertBefore(load,nav.lastElementChild);$('#start-btn').innerHTML='New journey <span>↗</span>';old.insertAdjacentHTML('beforeend','<aside id="title-right19" aria-label="Updates and saved journeys"></aside><div id="title-curtain19"></div><button class="title-next19" data-title19="scene" aria-label="Show another location">Explore another view <span>↻</span></button>');renderTitlePanel19();}
function removeSave19(slot){if(!['1','2','3'].includes(String(slot)))return false;try{for(const v of['v4','v3'])localStorage.removeItem('elyndor-save-'+v+'-'+slot);return true;}catch{toast('The browser could not remove this record.');return false;}}
function closeRecordDialog19(){const q=title19.confirmation;title19.confirmation=null;$('#record-dialog19')?.remove();q?.focus?.focus?.();}
function confirmRecord19(action,slot){if(!['1','2','3'].includes(String(slot)))return;closeRecordDialog19();const q=saveSummary19(slot),n=document.createElement('div');title19.confirmation={action,slot,focus:document.activeElement};n.id='record-dialog19';n.innerHTML=`<div class="record-dialog-shade19"></div><section role="dialog" aria-modal="true" aria-labelledby="record-title19"><p class="eyebrow">JOURNEY SLOT 0${slot}</p><h2 id="record-title19">${action==='delete'?'Delete this journey?':action==='save'?'Replace this record?':'Load this journey?'}</h2><p>${q.valid?esc(q.scene)+' · '+esc(savedDate19(q.savedAt)):q.raw?'This unreadable record will be removed.':'This slot is empty.'}</p><p>${action==='delete'?'The record in this slot will be permanently removed.':action==='save'?'Your current journey will replace the record in this slot.':'Your current unsaved progress will be replaced by this record.'}</p><div><button data-record19="cancel">${action==='delete'?'Keep record':action==='save'?'Keep existing':'Cancel'}</button><button data-record19="confirm" class="${action==='delete'?'danger':''}">${action==='delete'?'Delete slot 0'+slot:action==='save'?'Replace record':'Load journey'}</button></div></section>`;document.body.append(n);n.querySelector('[data-record19=cancel]').focus();}
function performRecord19(action,slot){if(action==='delete'){if(!removeSave19(slot))return;closeRecordDialog19();if(menu)renderMenu();renderTitlePanel19();toast('Journey slot 0'+slot+' deleted.');return;}closeRecordDialog19();if(action==='save')saveSlot(slot);else loadSlot(slot);renderTitlePanel19();}
const titleStartBefore19=startJourney;startJourney=async function(...args){title19.stopped=true;if(title19.task)await title19.task;for(const a of[player,...followers].filter(Boolean))a.mesh.visible=a.shadow.visible=true;return titleStartBefore19(...args);};
const titleLoadBefore19=loadSlot;loadSlot=function(...args){title19.stopped=true;const r=titleLoadBefore19(...args);if(!r)title19.stopped=false;return r;};
const titleSaveBefore19=saveSlot;saveSlot=function(...args){const r=titleSaveBefore19(...args);if(r)renderTitlePanel19();return r;};
const titleRenderMenuBefore19=renderMenu;renderMenu=function(...args){const r=titleRenderMenuBefore19(...args);if(menu?.tab==='save'){$('#menu-title').textContent='Journey records';$('#menu-content').innerHTML='<h3>The inn chronicle</h3><p class="desc">Choose one of three journey slots. Records remain in this browser. Your latest automatic inn checkpoint is available through Continue on the title screen.</p>'+saveCards19(true);}const back=$('#return-title');if(back)back.onclick=()=>{if(restoration)return toast('Let the restoration finish first.');autoSave();closeMenu();if(battle)endBattle('fled');state.mode='title';title19.stopped=false;title19.tab='news';title19.age=0;$('#title').classList.remove('hidden');$('#hud').classList.add('hidden');renderTitlePanel19();hideTitleParty19();switchTitleScene19();};return r;};
const titleCameraBefore19=updateCamera;updateCamera=function(dt,instant=false){if(state.mode!=='title'||!title19.focus)return titleCameraBefore19(dt,instant);const[x,z]=title19.focus,y=heightAt(x,z);cameraTarget.set(x,y+1,z);camera.position.copy(cameraTarget).add(V3(0,20,38));camera.fov=34;camera.lookAt(cameraTarget);camera.updateProjectionMatrix();camera.updateMatrixWorld();focusPoint.copy(cameraTarget);post.material.uniforms.focus.value=camera.position.distanceTo(cameraTarget);for(const a of actors)a.mesh.quaternion.copy(camera.quaternion);hideTitleParty19();};
const titleTickBefore19=tick;tick=function(dt){if(state.mode==='title')titleClock=-1000000;titleTickBefore19(dt);if(state.mode==='title'){titleClock=0;hideTitleParty19();if(!title19.stopped&&!title19.busy&&!menu&&!title19.confirmation&&title19.tab==='news'){title19.age+=dt;if(title19.age>22)switchTitleScene19();}}};
const titleRenderBefore19=render;render=function(...args){hideTitleParty19();return titleRenderBefore19(...args);};
const titleBootBefore19=boot;boot=async function(){await titleBootBefore19();if(!window.__ely)return;installTitle19();title19.stopped=false;await switchTitleScene19();const previous=window.render_game_to_text;window.render_game_to_text=()=>{const q=JSON.parse(previous());q.titleScreen={scene:title19.scene,partyVisible:state.mode==='title'&&[player,...followers].some(a=>a.mesh.visible),panel:title19.tab,slots:['1','2','3'].map(saveSummary19)};q.waterCurrent=world?.userData.currentMotion19??null;return JSON.stringify(q);};};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.record19){e.preventDefault();e.stopImmediatePropagation();const q=title19.confirmation;if(b.dataset.record19==='cancel')closeRecordDialog19();else if(q)performRecord19(q.action,q.slot);return;}if(b.dataset.title19){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.title19==='scene')switchTitleScene19();else{title19.tab=b.dataset.title19;renderTitlePanel19();$('#title-right19 h2')?.scrollIntoView({block:'nearest'});}return;}if(b.dataset.delete19||b.dataset.save||b.dataset.load){e.preventDefault();e.stopImmediatePropagation();const slot=b.dataset.delete19??b.dataset.save??b.dataset.load;if(b.dataset.delete19)return confirmRecord19('delete',slot);if(b.dataset.save)return saveSummary19(slot).raw?confirmRecord19('save',slot):performRecord19('save',slot);if(state.mode!=='title')return confirmRecord19('load',slot);loadSlot(slot);}},true);
document.addEventListener('keydown',e=>{const dialog=$('#record-dialog19');if(dialog){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape')return closeRecordDialog19();const bs=[...dialog.querySelectorAll('button')],i=bs.indexOf(document.activeElement);if(['Tab','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))bs[(i+(e.shiftKey||e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1)+bs.length)%bs.length].focus();if(e.key==='Enter'||e.key===' ')document.activeElement?.click();return;}if(state.mode==='title'&&!menu&&e.key==='Escape'&&title19.tab==='saves'){e.preventDefault();e.stopImmediatePropagation();title19.tab='news';renderTitlePanel19();$('#title-load19').focus();}},true);
